    startTransition(() => {
      setAlbumsPromise(refetchData('/the-beatles/albums'));
    });
  }

  return (
    <>

        {isPending ? 'Refreshing...' : 'Refresh'}

        }>

  );
}

function Albums({ albumsPromise }) {
  const albums = use(albumsPromise);
  return (

      {albums.map(album => (

          {album.title} ({album.year})

      ))}

  );
}

function Loading() {
  return Loading...;
}
```

